async def retry(op, attempts=3, timeout=1.0, base_delay=0.1):
    for i in range(attempts):
        try:
            return await asyncio.wait_for(op(), timeout)
        except Exception:
            if i == attempts - 1:
                raise
            await sleep(base_delay * 2 ** i)
